/* Generated by build.ps1. Cache name is a hash of app.html, so republishing evicts the old copy. */
'use strict';

const CACHE = 'cannaclub-mockup-0a3eccb31c47';

/* Everything the app needs is inlined into app.html, so the shell is four files. */
const ASSETS = [
  './',
  './app.html',
  './manifest.webmanifest',
  './app-icon-180.png',
  './app-icon-512.png'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      /* addAll fails the whole install if any single item 404s, so add them individually. */
      .then((cache) => Promise.all(ASSETS.map((a) => cache.add(a).catch(() => {}))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  /* Web fonts: kept the first time they load, so the installed app looks the same offline.
     (Published copy only; the mockup build in the CannaClub repo still leaves them to the network.) */
  const host = new URL(request.url).hostname;
  if (host === 'fonts.googleapis.com' || host === 'fonts.gstatic.com') {
    event.respondWith(
      caches.open(CACHE + '-fonts').then((cache) =>
        cache.match(request).then((hit) => hit || fetch(request).then((res) => {
          cache.put(request, res.clone());
          return res;
        }))
      )
    );
    return;
  }
  if (new URL(request.url).origin !== self.location.origin) return;

  /* A navigation always resolves to the app shell, so a deep link or a refresh while offline
     still opens the app rather than the browser's error page. */
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() => caches.match('./app.html').then((r) => r || Response.error()))
    );
    return;
  }

  event.respondWith(
    caches.match(request).then((cached) => cached || fetch(request))
  );
});